```openscad
// Tube adapter sleeve - printed upside down (collar on bed)
// Units: mm

$fn = 96;

// --- Dimensions ---
collar_d      = 17.0;   // collar outer diameter
collar_h      = 1.5;    // collar thickness (z = 0 to 1.5)
sleeve_od     = 14.0;   // sleeve body outer diameter
total_h       = 20.0;   // overall height (top of sleeve body)
bore_d        = 11.0;   // straight through-bore diameter
eps           = 0.5;    // cutter overshoot past faces
overlap       = 0.01;   // small overlap to fuse collar and sleeve

difference() {
    union() {
        // Collar resting on the bed
        cylinder(d = collar_d, h = collar_h);
        // Sleeve body rising from collar to total height
        translate([0, 0, collar_h - overlap])
            cylinder(d = sleeve_od, h = total_h - collar_h + overlap);
    }
    // Through-bore, open at both ends
    translate([0, 0, -eps])
        cylinder(d = bore_d, h = total_h + 2 * eps);
}
