```openscad
// Weighted base with vertical rod holder - printed upright
$fn = 96;

// --- Base disc ---
base_d      = 80.0;   // disc diameter
base_h      = 10.0;   // disc thickness (z = 0 to 10)

// --- Central boss ---
boss_d      = 24.0;   // boss diameter
boss_top_z  = 35.0;   // top of boss

// --- Rod bore (blind) ---
bore_d      = 10.0;   // rod bore diameter
bore_bot_z  = 10.0;   // bottom of blind bore

// --- Set-screw hole ---
screw_d     = 5.0;    // set-screw hole diameter
screw_z     = 29.0;   // height of set-screw axis

eps         = 0.5;    // overcut for clean differences

difference() {
    union() {
        // base disc
        cylinder(d = base_d, h = base_h);
        // boss, overlapping slightly into disc for a solid union
        translate([0, 0, base_h - eps])
            cylinder(d = boss_d, h = boss_top_z - base_h + eps);
    }

    // blind rod bore from top down to z = 10
    translate([0, 0, bore_bot_z])
        cylinder(d = bore_d, h = boss_top_z - bore_bot_z + eps);

    // radial set-screw hole from +X side into the bore
    translate([0, 0, screw_z])
        rotate([0, 90, 0])
            cylinder(d = screw_d, h = boss_d / 2 + eps);
}
