```openscad
// 8-well agarose gel comb, printed flat on the bed
// Units: mm

$fn = 64;

// ---- Parameters ----
thickness     = 2.5;   // plate thickness (Z)
spine_len     = 62;    // spine length (X)
spine_wid     = 8;     // spine width (Y)
n_teeth       = 8;     // number of teeth / wells
tooth_wid     = 4.0;   // tooth width (X)
tooth_len     = 12;    // tooth length (Y), hanging below spine
tooth_gap     = 3.0;   // gap between neighbouring teeth (X)
overlap       = 0.5;   // tooth overlap into spine for a clean union

// ---- Derived ----
row_len   = n_teeth * tooth_wid + (n_teeth - 1) * tooth_gap; // 53 mm
total_y   = spine_wid + tooth_len;                           // 20 mm
y_min     = -total_y / 2;                                    // bottom of teeth
spine_y0  = y_min + tooth_len;                               // spine lower edge
pitch     = tooth_wid + tooth_gap;                           // tooth pitch

// ---- Model ----
union() {
    // Spine (back bar)
    translate([-spine_len / 2, spine_y0, 0])
        cube([spine_len, spine_wid, thickness]);

    // Teeth
    for (i = [0 : n_teeth - 1])
        translate([-row_len / 2 + i * pitch, y_min, 0])
            cube([tooth_wid, tooth_len + overlap, thickness]);
}
```

