// Rigid in-line rod coupler, printed upright along Z

$fn = 96;

// ---- Dimensions (mm) ----
outer_d      = 18.0;   // coupler outer diameter
length       = 20.0;   // coupler length (Z height)
bore_d       = 6.0;    // axial rod bore diameter
screw_d      = 6.0;    // radial set-screw hole diameter
screw_z1     = length * 0.25; // first set-screw height (1/4 length)
screw_z2     = length * 0.75; // second set-screw height (3/4 length)
overcut      = 0.5;    // cutter overshoot past faces

// ---- Model ----
difference() {
    // Main body
    cylinder(d = outer_d, h = length);

    // Axial bore, full length
    translate([0, 0, -overcut])
        cylinder(d = bore_d, h = length + 2 * overcut);

    // Radial set-screw holes on +X side
    for (z = [screw_z1, screw_z2])
        translate([0, 0, z])
            rotate([0, 90, 0])
                cylinder(d = screw_d, h = outer_d / 2 + overcut);
}
