```openscad
// Small lab funnel - printed upright, wide opening at the top
// Built as a single rotate_extrude profile, so it is open top and bottom

$fn = 128;                 // smoothness of the round shapes

// ---------- Dimensions (mm) ----------
spout_od      = 8.0;       // spout outer diameter
spout_h       = 18;        // spout runs from z = 0 to this height
rim_od        = 50;        // cone outer diameter at the rim
rim_z         = 43;        // rim height (top of the funnel)
wall          = 1.6;       // wall thickness, measured at right angles to the wall

// ---------- Derived values ----------
spout_r_out   = spout_od / 2;                    // 4.0
spout_r_in    = spout_r_out - wall;              // 2.4 (4.8 mm bore)
rim_r_out     = rim_od / 2;                      // 25.0
cone_h        = rim_z - spout_h;                 // 25
cone_slope    = (rim_r_out - spout_r_out) / cone_h;   // radius change per mm of height
cone_cos      = cone_h / sqrt(cone_h*cone_h + (rim_r_out - spout_r_out)*(rim_r_out - spout_r_out));
cone_hoff     = wall / cone_cos;                 // horizontal offset that gives 1.6 mm at right angles to the wall
rim_r_in      = rim_r_out - cone_hoff;           // inner radius at the rim
// height where the inner cone surface meets the spout bore
join_z        = spout_h + (cone_hoff - wall) / cone_slope;

// ---------- Model ----------
rotate_extrude(convexity = 4)
    polygon(points = [
        [spout_r_in,  0],          // inner bottom of spout
        [spout_r_out, 0],          // outer bottom of spout
        [spout_r_out, spout_h],    // outer spout/cone junction
        [rim_r_out,   rim_z],      // outer rim
        [rim_r_in,    rim_z],      // inner rim
        [spout_r_in,  join_z]      // inner cone meets spout bore
    ]);
```

```openscad
// Flat drilling / marking jig
// Plate lies on the bed (z = 0), centred on the origin in X and Y.

$fn = 64;

// ---------------- Plate ----------------
plate_len   = 100;   // plate length along X
plate_wid   = 84;    // plate width along Y
plate_thk   = 4;     // plate thickness along Z

// ---------------- Hole grid ----------------
hole_d      = 3.4;   // through-hole diameter
holes_x     = 6;     // number of holes along X
holes_y     = 5;     // number of holes along Y
pitch_x     = 15;    // centre-to-centre spacing along X
pitch_y     = 15;    // centre-to-centre spacing along Y

// ---------------- Orientation notch (+Y edge) ----------------
notch_w     = 12;    // notch width along X
notch_d     = 5;     // notch depth along Y (in from the +Y edge)

// ---------------- Helpers ----------------
eps         = 0.5;   // overcut so cutters pass through faces

grid_span_x = (holes_x - 1) * pitch_x;   // 75 mm
grid_span_y = (holes_y - 1) * pitch_y;   // 60 mm

difference() {
    // Base plate
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // 6 x 5 grid of through-holes, centred on the plate
    for (i = [0 : holes_x - 1])
        for (j = [0 : holes_y - 1])
            translate([-grid_span_x / 2 + i * pitch_x,
                       -grid_span_y / 2 + j * pitch_y,
                       -eps])
                cylinder(d = hole_d, h = plate_thk + 2 * eps);

    // Rectangular orientation notch in the +Y edge, centred on X = 0
    translate([-notch_w / 2, plate_wid / 2 - notch_d, -eps])
        cube([notch_w, notch_d + eps, plate_thk + 2 * eps]);
}
