```openscad
// Bench rack for 24 x 5 mL round-bottom tubes
// Print orientation: block flat on bed, holes open upward (+Z)

// ---------- Block dimensions ----------
block_len   = 152;   // block length along X (mm)
block_wid   = 66;    // block width along Y (mm)
block_h     = 24;    // block height along Z (mm)

// ---------- Hole grid ----------
n_cols      = 8;     // holes per row (along X)
n_rows      = 3;     // number of rows (along Y)
pitch_x     = 17;    // centre-to-centre spacing along X (mm)
pitch_y     = 17;    // centre-to-centre spacing along Y (mm)

// ---------- Hole geometry ----------
hole_d      = 13.2;  // hole diameter (mm)
hole_depth  = 19;    // hole depth from top face (mm)
floor_t     = block_h - hole_depth; // solid floor thickness = 5 mm

// ---------- Misc ----------
overcut     = 0.5;   // extension of cutters past the top face (mm)
$fn         = 96;    // facet count for round holes

// Grid offsets so the hole pattern is centred on the block
grid_x0 = -(n_cols - 1) * pitch_x / 2;
grid_y0 = -(n_rows - 1) * pitch_y / 2;

difference() {
    // Solid block, centred in X/Y, resting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_h]);

    // 3 x 8 grid of blind holes, open at the top
    for (i = [0 : n_cols - 1])
        for (j = [0 : n_rows - 1])
            translate([grid_x0 + i * pitch_x,
                       grid_y0 + j * pitch_y,
                       floor_t])
                cylinder(d = hole_d, h = hole_depth + overcut, $fn = $fn);
}
```

```openscad
// Snap-on C-clip for a 12.7 mm lab-stand rod
// Printed flat: 2-D profile in XY, extruded along +Z

$fn = 128;

// ---------------- Parameters ----------------
rod_d        = 12.7;              // inner diameter (rod diameter)
wall         = 2.5;               // ring wall thickness
outer_d      = rod_d + 2*wall;    // outer diameter = 17.7
clip_h       = 15;                // extrusion height (Z)
gap_half     = 4.0;               // opening spans -4.0 < y < 4.0 (as specified)
cut_x_max    = 0;                 // opening removes everything with x < 0
eps          = 0.5;               // overshoot for clean cuts

// ---------------- Model ----------------
difference() {
    // Ring
    difference() {
        cylinder(d = outer_d, h = clip_h);
        translate([0, 0, -eps])
            cylinder(d = rod_d, h = clip_h + 2*eps);
    }

    // Snap opening on the -X side
    translate([-(outer_d/2 + eps), -gap_half, -eps])
        cube([outer_d/2 + eps + cut_x_max, 2*gap_half, clip_h + 2*eps]);
}
```

```openscad
// Two-part enclosure: box + lid (lid printed upside down), side by side on the bed

$fn = 64;

// ---------------- Box dimensions ----------------
box_x      = 70;    // box outer length (X)
box_y      = 50;    // box outer width (Y)
box_z      = 25;    // box outer height (Z)
wall_t     = 2.5;   // box wall thickness
floor_t    = 2.5;   // box floor thickness

// ---------------- Lid dimensions ----------------
lid_x      = 70;    // lid plate length (X)
lid_y      = 50;    // lid plate width (Y)
lid_t      = 2.5;   // lid plate thickness
lip_x      = 64.6;  // lip outer length (X), 0.2 mm clearance per side
lip_y      = 44.6;  // lip outer width (Y), 0.2 mm clearance per side
lip_wall   = 1.2;   // lip wall thickness
lip_h      = 5;     // lip height above plate

// ---------------- Layout ----------------
gap        = 10;    // gap between box and lid on the bed
eps        = 0.5;   // cutter overshoot to avoid coplanar faces
join       = 0.01;  // small overlap for unions

// Centres so the pair is centred on the origin in X
total_x    = box_x + gap + lid_x;
box_cx     = -total_x / 2 + box_x / 2;
lid_cx     =  total_x / 2 - lid_x / 2;

// ---------------- Part 1: Box ----------------
module box() {
    difference() {
        // outer shell
        translate([-box_x / 2, -box_y / 2, 0])
            cube([box_x, box_y, box_z]);
        // inner cavity, open top
        translate([-(box_x - 2 * wall_t) / 2, -(box_y - 2 * wall_t) / 2, floor_t])
            cube([box_x - 2 * wall_t, box_y - 2 * wall_t, box_z - floor_t + eps]);
    }
}

// ---------------- Part 2: Lid (upside down) ----------------
module lid() {
    union() {
        // plate lying on the bed
        translate([-lid_x / 2, -lid_y / 2, 0])
            cube([lid_x, lid_y, lid_t]);
        // rectangular lip on top of the plate
        difference() {
            translate([-lip_x / 2, -lip_y / 2, lid_t - join])
                cube([lip_x, lip_y, lip_h + join]);
            translate([-(lip_x - 2 * lip_wall) / 2, -(lip_y - 2 * lip_wall) / 2, lid_t - eps])
                cube([lip_x - 2 * lip_wall, lip_y - 2 * lip_wall, lip_h + 2 * eps]);
        }
    }
}

// ---------------- Assembly on the bed ----------------
translate([box_cx, 0, 0]) box();
translate([lid_cx, 0, 0]) lid();
```

```openscad
// 6-place holder for 2 mL cryovials, printed upright
// Units: mm

// ---- Block ----
block_len   = 120;   // X length
block_wid   = 30;    // Y width
block_ht    = 25;    // Z height

// ---- Holes ----
n_holes     = 6;     // number of vial positions
hole_pitch  = 18;    // centre-to-centre spacing along X
hole_dia    = 12.5;  // hole diameter
hole_depth  = 20;    // blind hole depth from top
floor_th    = block_ht - hole_depth; // remaining floor (5 mm)

// ---- Misc ----
eps         = 0.5;   // overshoot for clean boolean cuts
$fn         = 96;    // curve resolution

difference() {
    // Solid block, centred in X/Y, resting on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_ht]);

    // Row of blind holes, centred on the block
    for (i = [0 : n_holes - 1]) {
        x = (i - (n_holes - 1)/2) * hole_pitch;
        translate([x, 0, floor_th])
            cylinder(d = hole_dia, h = hole_depth + eps, $fn = 96);
    }
}
