```openscad
// Push-on cap for a 10.0 mm OD tube, printed open-end up
// Units: mm

$fn = 96;

// --- Dimensions ---
cap_od        = 14.6;   // outer diameter of cap
cap_h         = 12.0;   // total height of cap
bore_d        = 10.6;   // blind bore diameter (10.0 tube + 0.6 clearance)
floor_t       = 3.0;    // closed bottom thickness
groove_count  = 10;     // number of vertical grip grooves
groove_d      = 2.0;    // grip groove diameter (half-cylinder on outer surface)
eps           = 0.5;    // overcut to avoid coplanar faces

cap_r    = cap_od / 2;
bore_h   = cap_h - floor_t;

difference() {
    // Main body
    cylinder(d = cap_od, h = cap_h);

    // Blind bore from the top
    translate([0, 0, floor_t])
        cylinder(d = bore_d, h = bore_h + eps);

    // Vertical grip grooves, centred on the outer surface
    for (i = [0 : groove_count - 1])
        rotate([0, 0, i * 360 / groove_count])
            translate([cap_r, 0, -eps])
                cylinder(d = groove_d, h = cap_h + 2 * eps, $fn = 48);
}
```

```openscad
// Replacement control knob for 6.0 mm D-shaft
// Print orientation: hotplate-facing (bore) side down on the bed

// ---------------- Parameters ----------------
knob_d        = 34;    // knob outer diameter
knob_h        = 12;    // knob total height

bore_d        = 6.2;   // D-bore circle diameter (clearance for 6.0 mm shaft)
bore_flat     = 4.9;   // distance from flat to opposite side of bore circle
bore_depth    = 7;     // blind bore depth from bottom face

groove_count  = 16;    // number of vertical grip grooves
groove_d      = 2;     // groove diameter (half-cylinder centred on outer surface)

eps           = 0.5;   // overshoot for clean boolean cuts
$fn           = 96;    // curve resolution

// ---------------- Derived ----------------
knob_r     = knob_d / 2;
bore_r     = bore_d / 2;
flat_x     = bore_flat - bore_r;   // flat position from bore centre (+X side)

// ---------------- Modules ----------------
module d_bore() {
    // D-shaped blind bore, from just below z=0 up to bore_depth
    translate([0, 0, -eps])
    intersection() {
        cylinder(h = bore_depth + eps, r = bore_r, $fn = 64);
        // keep everything on the -X side of the flat
        translate([-bore_r - 1, -bore_r - 1, -0.01])
            cube([flat_x + bore_r + 1, bore_d + 2, bore_depth + eps + 0.02]);
    }
}

module grip_grooves() {
    for (i = [0 : groove_count - 1])
        rotate([0, 0, i * 360 / groove_count])
            translate([knob_r, 0, -eps])
                cylinder(h = knob_h + 2 * eps, d = groove_d, $fn = 64);
}

// ---------------- Part ----------------
difference() {
    cylinder(h = knob_h, r = knob_r);
    d_bore();
    grip_grooves();
}
```

