    union() {
        // Base disc
        cylinder(d = disc_d, h = disc_h);
        // Boss (overlaps disc slightly for a clean union)
        translate([0, 0, disc_h - eps])
            cylinder(d = boss_d, h = boss_top - disc_h + eps);
    }

    // Blind rod bore from top of boss down to z = 8
    translate([0, 0, bore_bottom])
        cylinder(d = bore_d, h = boss_top - bore_bottom + eps);

    // Radial set-screw hole from +X side into the bore
    translate([0, 0, screw_z])
        rotate([0, 90, 0])
            cylinder(d = screw_d, h = boss_d / 2 + eps, $fn = 64);
