// L-shaped mounting bracket
// Print orientation: base plate flat on the bed (z = 0), vertical plate builds up along +Z

$fn = 64;

// ---------- Base plate ----------
base_x_min   = -20;   // base plate X start
base_x_max   = 20;    // base plate X end
base_y_min   = 0;     // base plate Y start (back edge)
base_y_max   = 50;    // base plate Y end (front edge)
base_thick   = 5;     // base plate thickness (Z)

// ---------- Vertical plate ----------
vert_x_min   = -20;   // vertical plate X start
vert_x_max   = 20;    // vertical plate X end
vert_y_min   = 0;     // vertical plate Y start
vert_y_max   = 5;     // vertical plate Y end (thickness)
vert_height  = 45;    // vertical plate height (Z)

// ---------- Holes ----------
hole_d       = 4.5;   // through-hole diameter (both plates)
base_hole_xs = [-14, 14]; // base hole X positions
base_hole_y  = 40;        // base hole Y position
vert_hole_xs = [-14, 14]; // vertical plate hole X positions
vert_hole_z  = 27;        // vertical plate hole Z position

eps = 0.5;            // cutter overshoot past faces

difference() {
    union() {
        // Base plate
        translate([base_x_min, base_y_min, 0])
            cube([base_x_max - base_x_min, base_y_max - base_y_min, base_thick]);

        // Vertical plate
        translate([vert_x_min, vert_y_min, 0])
            cube([vert_x_max - vert_x_min, vert_y_max - vert_y_min, vert_height]);
