// Small lab funnel - printed upright, wide opening at top
// Built as a single revolved wall profile (no boolean cuts needed)

// ---------------- Parameters ----------------
spout_od     = 14.0;   // spout outer diameter
spout_len    = 20.0;   // spout height (z = 0 .. 20)
rim_od       = 60.0;   // cone outer diameter at rim
total_h      = 50.0;   // rim height (top of funnel)
wall         = 2.4;    // wall thickness (normal to the surface)
$fn          = 128;    // smoothness of revolved surfaces

// ---------------- Derived values ----------------
ro_s   = spout_od / 2;               // spout outer radius (7.0)
ri_s   = ro_s - wall;                // spout inner radius (4.6 -> 9.2 bore)
ro_rim = rim_od / 2;                 // rim outer radius (30.0)
cone_h = total_h - spout_len;        // cone height (30)

// Cone wall angle from vertical; radial offset that gives a true
// perpendicular wall thickness of 'wall' on the sloped surface
cone_slope = (ro_rim - ro_s) / cone_h;            // dr/dz
radial_off = wall * sqrt(1 + cone_slope * cone_slope);

ri_rim = ro_rim - radial_off;        // rim inner radius

// Height where inner cone surface meets the spout bore
z_knee = spout_len + (ri_s - (ro_s - radial_off)) / cone_slope;

// ---------------- Model ----------------
rotate_extrude(convexity = 4)
    polygon(points = [
        [ri_s,   0],          // bore, bottom
        [ro_s,   0],          // spout outside, bottom
        [ro_s,   spout_len],  // spout/cone transition (outside)
        [ro_rim, total_h],    // rim outside
        [ri_rim, total_h],    // rim inside
        [ri_s,   z_knee]      // inner cone meets bore
    ]);
