// as -5.0 < y < 5.0 (= 10.0 mm). The explicit cut region is used below;
// change gap_half to 4.95 for a 9.9 mm opening.

// ---------------- Parameters ----------------
rod_d     = 16.0;            // rod diameter = ring inner diameter
wall      = 3.0;             // ring wall thickness
outer_d   = rod_d + 2*wall;  // ring outer diameter (22.0 mm)
height    = 8.0;             // extrusion height (Z)
gap_half  = 5.0;             // opening spans -gap_half < y < gap_half on the -X side
eps       = 0.5;             // cutter overshoot past cut faces
$fn       = 128;             // smoothness of curved faces

// ---------------- Model ----------------
difference() {
    // Ring
    difference() {
        cylinder(d = outer_d, h = height);
        translate([0, 0, -eps])
            cylinder(d = rod_d, h = height + 2*eps);
    }

    // Snap-on opening: remove everything with x < 0 and |y| < gap_half.
    // It extends slightly past x = 0 only inside the bore, where there is
    // no material, so the cut is unchanged.
    translate([-(outer_d/2 + eps), -gap_half, -eps])
        cube([outer_d/2 + eps + 0.01, 2*gap_half, height + 2*eps]);
