lip_y     = 40.4;   // lip outer width (Y)
lip_wall  = 1.2;    // lip wall thickness
lip_h     = 3.0;    // lip height above plate

// ---------- Layout ----------
gap       = 10.0;   // gap between parts on the bed
eps       = 0.5;    // cutter overshoot to avoid coplanar faces

// Centres of each part so the pair is centred on the origin in X
box_cx = -(box_x / 2 + gap / 2);
lid_cx =  (lid_x / 2 + gap / 2);

// ---------- Part 1: box ----------
module box() {
    difference() {
        translate([-box_x / 2, -box_y / 2, 0])
            cube([box_x, box_y, box_z]);
        // inner cavity, open top
        translate([-(box_x - 2 * wall) / 2, -(box_y - 2 * wall) / 2, floor_t])
            cube([box_x - 2 * wall, box_y - 2 * wall, box_z - floor_t + eps]);
    }
}

// ---------- Part 2: lid (printed upside down) ----------
module lid() {
    union() {
        // plate on the bed
        translate([-lid_x / 2, -lid_y / 2, 0])
            cube([lid_x, lid_y, lid_t]);
        // rectangular lip on top of the plate
        difference() {
            translate([-lip_x / 2, -lip_y / 2, lid_t - 0.01])
                cube([lip_x, lip_y, lip_h + 0.01]);
            translate([-(lip_x - 2 * lip_wall) / 2, -(lip_y - 2 * lip_wall) / 2, lid_t])
                cube([lip_x - 2 * lip_wall, lip_y - 2 * lip_wall, lip_h + eps]);
        }
    }
}

// ---------- Assembly on the bed ----------
translate([box_cx, 0, 0]) box();
translate([lid_cx, 0, 0]) lid();
