                       grid_y0 + j * hole_pitch,
                       -eps])
                cylinder(d = hole_d, h = plate_t + 2 * eps);

    // Rectangular orientation notch in the +Y edge
    translate([-notch_w / 2,
               plate_w / 2 - notch_d,
