// Small lab funnel - printed upright, wide opening at top
// Built as a revolved wall profile, open at the top and the bottom

// ---------------- Parameters ----------------
spout_od      = 10.0;  // spout outer diameter
spout_h       = 22.0;  // spout height (z = 0 to 22)
rim_od        = 50.0;  // cone outer diameter at the rim
rim_z         = 57.0;  // rim height (top of cone)
wall          = 2.0;   // wall thickness, measured normal to the wall
$fn           = 128;   // smoothness of the revolved surfaces

// ---------------- Derived values ----------------
r_spout_o = spout_od / 2;            // 5.0  spout outer radius
r_spout_i = r_spout_o - wall;        // 3.0  spout bore radius (6.0 mm bore)
r_rim_o   = rim_od / 2;              // 25.0 rim outer radius
cone_h    = rim_z - spout_h;         // 35.0 cone height
k         = (r_rim_o - r_spout_o) / cone_h;   // radius change per mm of height
h_off     = wall * sqrt(1 + k * k);  // horizontal offset that gives 2.0 mm normal wall
r_rim_i   = r_rim_o - h_off;         // inner radius at the rim
// Height where the inner cone surface meets the spout bore
z_knee_i  = spout_h + (r_spout_i - (r_spout_o - h_off)) / k;

// ---------------- Model ----------------
// Cross-section of the wall (X = radius, Y = height), revolved about Z
rotate_extrude(convexity = 4)
    polygon(points = [
        [r_spout_i, 0],          // bottom of the bore
        [r_spout_o, 0],          // bottom of the outer spout
        [r_spout_o, spout_h],    // outer spout meets the cone
        [r_rim_o,   rim_z],      // outer edge of the rim
        [r_rim_i,   rim_z],      // inner edge of the rim
        [r_spout_i, z_knee_i]    // inner cone meets the bore
    ]);
