// Small lab funnel - printed upright, wide opening at top
// Single solid built with rotate_extrude of a 2D wall profile.

$fn = 128;

// ---------------- Dimensions (mm) ----------------
spout_od     = 8.0;   // spout outer diameter
spout_h      = 15.0;  // spout runs from z = 0 to z = spout_h
rim_od       = 40.0;  // cone outer diameter at the rim
rim_z        = 40.0;  // height of the rim (top of funnel)
wall         = 2.4;   // wall thickness (normal to surface)

// ---------------- Derived values ----------------
spout_r      = spout_od / 2;                // 4.0
bore_r       = spout_r - wall;              // 1.6 -> 3.2 mm bore
rim_r        = rim_od / 2;                  // 20.0
cone_h       = rim_z - spout_h;             // 25.0
cone_slope   = (rim_r - spout_r) / cone_h;  // radial change per mm of height
cone_angle   = atan(cone_slope);            // angle of cone wall from vertical
wall_radial  = wall / cos(cone_angle);      // radial offset giving true 2.4 mm normal wall

// Inner cone surface: r_in(z) = spout_r + cone_slope*(z - spout_h) - wall_radial
rim_inner_r  = rim_r - wall_radial;         // inner radius at the rim
// Height where the inner cone surface meets the spout bore
join_z       = spout_h + (bore_r - (spout_r - wall_radial)) / cone_slope;

// ---------------- Model ----------------
module funnel_profile() {
    polygon(points = [
        [bore_r,      0],        // bottom of bore
        [spout_r,     0],        // bottom outer edge of spout
        [spout_r,     spout_h],  // top of straight spout (outer)
        [rim_r,       rim_z],    // outer rim
        [rim_inner_r, rim_z],    // inner rim
        [bore_r,      join_z]    // inner cone meets the spout bore
    ]);
}

rotate_extrude(convexity = 4, $fn = 128)
    funnel_profile();
